{
  "requirement_id": "REQ-008",
  "summary": "僅專案 owner 或任務建立者具備刪除任務的權限，否則回傳 403 錯誤且任務維持不變。",
  "acceptance_criteria": [
    "成功刪除任務時，API 回傳 204 狀態碼。",
    "專案 owner 或任務建立者可以成功刪除任務。",
    "其他專案成員嘗試刪除任務時，回傳 403 狀態碼且任務仍存在。",
    "非專案成員嘗試刪除任務時，回傳 403 狀態碼。"
  ]
}

{
  "summary": "僅專案 owner 或任務建立者具備刪除任務的權限，否則回傳 403 錯誤且任務維持不變。",
  "acceptance_criteria": [
    "成功刪除任務時，API 回傳 204 狀態碼。",
    "專案 owner 或任務建立者可以成功刪除任務。",
    "其他專案成員嘗試刪除任務時，回傳 403 狀態碼且任務仍存在。",
